// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address candidate, address querier) public {
        vm.assume(candidate != address(0));
        vm.assume(querier != address(0));
        vm.assume(querier != candidate);

        vm.prank(address(this));
        c.transferOwnership(candidate);

        vm.prank(querier);
        address reported = c.owner();

        assertTrue(reported == candidate);
    }
}
